<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$user=require_permission('power_user','procurement','custodian');
$items=db()->query("SELECT i.id,i.lot_number,i.title,i.status AS item_status,i.opening_price_cents,i.minimum_increment_cents,a.title AS auction_title,a.status AS auction_status,(SELECT COUNT(*) FROM approval_requests r WHERE r.entity_type='auction_item' AND r.entity_id=i.id AND r.status='pending') AS pending_requests FROM auction_items i JOIN auctions a ON a.id=i.auction_id ORDER BY a.created_at DESC,a.id DESC,CAST(i.lot_number AS INTEGER),i.lot_number")->fetchAll();
require dirname(__DIR__).'/app/layout.php';render_page_start('Procurement workspace','procurement',$user);
?>
<section class="welcome"><div><p class="eyebrow">PROCUREMENT WORKSPACE</p><h1>Item change requests</h1><p class="muted">Review the current catalogue and submit item changes for approval. Approved changes are applied only after a separate approver reviews them.</p></div><div class="welcome-icon">⇄</div></section>
<div class="notice"><span class="notice-dot"></span><div><strong>Two-person review</strong><p>Submitting a request does not change the item. The requester cannot approve their own request, and requests become stale if the item changes before review.</p></div></div>
<section class="content-panel"><div class="section-heading"><div><p class="eyebrow">CATALOGUE ITEMS</p><h2>All auction items</h2></div><span class="status-pill"><?= count($items) ?> items</span></div>
<?php if(!$items): ?><div class="empty-state"><strong>No items have been created</strong><p>Items will appear here once an administrator creates an auction catalogue.</p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Auction / item</th><th>Current status</th><th>Opening price</th><th>Approval status</th><th>Action</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= e($item['title']) ?></strong><small class="table-sub">Lot <?= e($item['lot_number']) ?> · <?= e($item['auction_title']) ?></small></td><td><span class="status-pill"><?= e(ucfirst($item['item_status'])) ?></span><small class="table-sub">Auction: <?= e($item['auction_status']) ?></small></td><td>N$ <?= e(number_format(((int)$item['opening_price_cents'])/100,2)) ?></td><td><?php if((int)$item['pending_requests']>0): ?><span class="status-pill">Pending review</span><?php else: ?><span class="muted">No pending request</span><?php endif; ?></td><td><?php if($item['item_status']==='awarded'): ?><span class="muted">Locked</span><?php elseif((int)$item['pending_requests']>0): ?><span class="muted">Awaiting review</span><?php else: ?><a class="text-link" href="<?= e(app_url('request-item-change.php?id='.(int)$item['id'])) ?>">Request change →</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php render_page_end(); ?>